<?php require_once __DIR__.'/functions.php'; $rooms=db()->query("SELECT * FROM rooms WHERE status='active' ORDER BY id")->fetchAll(); header_html('Rooms'); ?><main class="container py-5"><div class="gold fw-bold text-uppercase">Our rooms</div><h1 class="display-5 fw-bold">Choose your stay</h1><p class="text-secondary mb-4">Live room information comes from the hotel database.</p><div class="row g-4"><?php foreach($rooms as $r): ?><div class="col-md-4"><div class="card h-100 shadow-sm"><img class="room-img" src="<?=e($r['image'])?>"><div class="card-body"><h3><?=e($r['name'])?></h3><p class="text-secondary"><?=e($r['description'])?></p><div class="fw-bold gold fs-5">TZS <?=number_format($r['price'])?> / night</div><div class="mt-2">Up to <?=e($r['capacity'])?> guests</div><a href="booking.php?room=<?=$r['id']?>" class="btn btn-gold mt-3">Book now</a></div></div></div><?php endforeach; ?></div></main><?php footer_html(); ?>